                                                                                                                                                                '773 '
                                                                                                                                                                'change '
                                                                                                                                                                'rain '
                                                                                                                                                                'features '
                                                                                                                                                                'and '
                                                                                                                                                                '6,061 '
                                                                                                                                                                'are '
                                                                                                                                                                'isolated-profile '
                                                                                                                                                                'copies. '
                                                                                                                                                                'Constrained '
                                                                                                                                                                'synthesis '
                                                                                                                                                                'preserves '
                                                                                                                                                                'consistency '
                                                                                                                                                                'but '
                                                                                                                                                                'cannot '
